algorithms.pseudocode:
loop every 1s:
  ids = ZRANGEBYSCORE inflight:{qs} -inf now LIMIT 0 500
  for id in ids:
    ZREM inflight:{qs} id; DECR conc:{q}
    if attempt(id) >= max: toDLQ(id, 'lease expired')
    else ZADD ready:{qs} now id   -- redelivery
  due = ZRANGEBYSCORE delay:{qs} -inf now LIMIT 0 500
  move due -> ready
